  checkpoint:[q('A current-manual question retrieved an obsolete revision. The model quoted it accurately.','Which candidate directly addresses the observed failure?',['A revision-aware retrieval filter with tests','A more enthusiastic system prompt','A larger output token allowance'],0,'The first divergence is which evidence the tool returns.'),tf('The repaired prompt refuses all requests, including well-supported ones.','Testing only unsupported answers can miss this regression.',true,'The evaluation also needs permitted, useful requests.')],
  quiz:[q('Required cases: A,B. A passes with no critical violation in 100 ms. B has no result. Limit: 500 ms.','What should the gate return?',['Eligible, because A passed','Hold, because B is missing'],1,'Coverage is part of the declared acceptance rule.'),tf('All recorded cases pass the gate.','The result permits an unrestricted rollout without monitoring.',false,'The result only establishes eligibility for the limited trial defined by these checks.')],
  practice:[challenge('Can the candidate enter a limited trial?',['Implement trial_decision(required, results, max_ms). Return decision and reasons in required-case order. A missing result adds “ID: missing”. Otherwise check task failure, critical violation, then latency greater than max_ms, in that order, using the strings shown in the worked rule. An empty required list adds “no required cases”. Reject duplicate or undeclared result IDs, duplicate required IDs, nonboolean outcomes and invalid integer latency values with ValueError.'], 'def trial_decision(required, results, max_ms):\n    pass',trialSolution,"{'decision': 'hold', 'reasons': ['revision: missing']}",['Start from required IDs so missing measurements remain visible.','Check every reason for a present case. A critical violation can coexist with a passing task label.'],[['Passing at the latency boundary','assert trial_decision(["a"], [{"id":"a","passed":True,"critical":False,"ms":500}], 500) == {"decision":"eligible for limited trial","reasons":[]}'],['Failures and missing results','assert trial_decision(["a","b"], [{"id":"a","passed":False,"critical":True,"ms":501}], 500) == {"decision":"hold","reasons":["a: task failed","a: critical violation","a: too slow","b: missing"]}'],['Empty and malformed evidence','assert trial_decision([], [], 0)["decision"] == "hold"\n'+invalid('trial_decision(["a"], [{"id":"a","passed":True,"critical":False,"ms":True}], 500)')+'\n'+invalid('trial_decision(["a","a"], [], 500)')]])],
  build:build('Carry the repaired agent into a fresh shift','The old failure passes. Botie now needs the whole candidate report, including the request whose worker did not return.','Join results to required IDs, then apply the stated all-cases rule: every task passes, no critical violation is observed, and each latency is at most the limit. Return hold with reasons, or eligible for limited trial.',{required:'Required case IDs',results:'Candidate measurements',maximum:'Maximum milliseconds per case'},[sample('The retained checks pass',{required:['current','missing'],results:[result('current',true,false,400),result('missing',true,false,700)],maximum:1000},{decision:'eligible for limited trial',reasons:[]}),sample('A fresh permission case never returns',{required:['current','approval'],results:[result('current',true,false,400)],maximum:1000},{decision:'hold',reasons:['approval: missing']}),sample('The answer passes but a forbidden write occurs',{required:['approval'],results:[result('approval',true,true,500)],maximum:1000},{decision:'hold',reasons:['approval: critical violation']}),sample('A correct answer exceeds the limit',{required:['slow'],results:[result('slow',true,false,1001)],maximum:1000},{decision:'hold',reasons:['slow: too slow']})],op('aiTrialDecision',op('aiCandidateCoverage',s('required'),s('results')),s('maximum')),'Coverage and acceptance remain separate. An absent observation cannot disappear before the acceptance check.',replay,['Join onto required IDs, not onto the list of completed results.','Feed the complete joined list and the latency limit to the trial check.']),
